// Build 6 framework queries, one item per framework.
// Each item fires the GitHub Code Search node once.
const yesterday = new Date();
yesterday.setUTCDate(yesterday.getUTCDate() - 1);
const pushedSince = yesterday.toISOString().split('T')[0];

const frameworks = [
  { framework: 'LangChain',  query: 'from langchain_openai import language:Python' },
  { framework: 'LlamaIndex', query: 'from llama_index.core import language:Python' },
  { framework: 'LangGraph',  query: 'from langgraph.graph import language:Python' },
  { framework: 'CrewAI',     query: 'from crewai import Agent language:Python' },
  { framework: 'Haystack',   query: 'from haystack import Pipeline language:Python' },
  { framework: 'AutoGen',    query: 'from autogen import language:Python' }
];

return frameworks.map(f => ({ json: { ...f, pushedSince } }));

// Flatten all framework searches into unique org-level records.
// One record per (org, repo) pair — we only keep first repo seen per org.
const allItems = $input.all();
const seenOrgs = new Set();
const out = [];

for (const item of allItems) {
  const framework = item.json.framework;
  const hits = item.json.items || [];
  for (const hit of hits) {
    const repo = hit.repository;
    if (!repo || repo.fork) continue;
    const ownerType = repo.owner && repo.owner.type;
    if (ownerType !== 'Organization' && ownerType !== 'User') continue;
    const orgLogin = repo.owner.login;
    if (seenOrgs.has(orgLogin)) continue;
    seenOrgs.add(orgLogin);
    out.push({
      json: {
        framework,
        org_login: orgLogin,
        org_type: ownerType,
        org_api_url: `https://api.github.com/users/${orgLogin}`,
        repo_full_name: repo.full_name,
        repo_url: repo.html_url,
        repo_description: repo.description || '',
        file_path: hit.path,
        file_html_url: hit.html_url,
        detected_at: new Date().toISOString()
      }
    });
  }
}
return out;

// Keep only orgs not touched in the last 90 days per the qualification doc.
const newOrgs  = $('Flatten + Extract Orgs').all().map(i => i.json);
const contacted = $input.all().map(i => i.json);

const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
const seen = new Set();
for (const row of contacted) {
  const ts = Date.parse(row.timestamp || row.detected_at || 0);
  if (row.org_login && (isNaN(ts) || ts >= ninetyDaysAgo)) {
    seen.add(String(row.org_login).toLowerCase());
  }
}

const fresh = newOrgs.filter(o => !seen.has(String(o.org_login).toLowerCase()));
return fresh.map(f => ({ json: f }));

// Merge GitHub org metadata back with the signal context, extract a domain.
const signals = $('Dedup Against State').all().map(i => i.json);
const orgResponses = $input.all().map(i => i.json);

function domainFromUrl(url) {
  if (!url) return null;
  try {
    const u = new URL(url.startsWith('http') ? url : `https://${url}`);
    return u.hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    return null;
  }
}

const out = [];
for (let i = 0; i < signals.length; i++) {
  const sig = signals[i];
  const org = orgResponses[i] || {};
  const domain = domainFromUrl(org.blog) || domainFromUrl(org.email && org.email.split('@')[1]);
  if (!domain) continue;
  out.push({
    json: {
      ...sig,
      company_name: org.name || org.login,
      company_bio: org.bio || org.description || '',
      company_location: org.location || '',
      company_blog: org.blog || '',
      company_public_repos: org.public_repos || 0,
      company_followers: org.followers || 0,
      company_domain: domain
    }
  });
}
return out;

// Weighted ICP scoring per docs/icp.md.
// Works with or without Clay enrichment — Clay data just sharpens the score.
const clayOn = String($env.CLAY_ENABLED || 'false').toLowerCase() === 'true';
const signals = $('Extract Domain').all().map(i => i.json);
const clayData = clayOn ? $input.all().map(i => i.json) : [];

function scoreOne(sig, clay) {
  const size     = clay && clay.employee_count ? Number(clay.employee_count) : (sig.company_public_repos * 5 || 25);
  const industry = clay && clay.industry ? String(clay.industry).toLowerCase() : '';
  const country  = clay && clay.country ? String(clay.country).toUpperCase() : '';

  const frameworkRecency = 10;
  const teamSizeFit      = size >= 30 && size <= 150 ? 10 : size >= 10 && size <= 500 ? 7 : 3;
  const aiNative         = /(^|\b)(ai|ml|llm|agent|retriev|rag)($|\b)/.test(`${sig.company_bio} ${sig.repo_description} ${industry}`) ? 10 : 5;
  const fundingGrowth    = clay && clay.last_funding_amount ? 10 : 5;
  const geography        = ['US','GB','DE','NL','FR','ES','IT','IE','PL','LT','CZ','PT','SE','DK','FI','IL'].includes(country) ? 10 : (country ? 4 : 6);
  const frameworkFit     = ['LangChain','LlamaIndex','LangGraph'].includes(sig.framework) ? 10 : 8;

  const raw = frameworkRecency * 2.5 + teamSizeFit * 2.0 + aiNative * 2.0 + fundingGrowth * 1.5 + geography * 1.0 + frameworkFit * 1.0;
  const score = Math.round(raw);
  const tier = score >= 80 ? 1 : score >= 60 ? 2 : score >= 40 ? 3 : 0;
  return { score, tier };
}

const out = [];
for (let i = 0; i < signals.length; i++) {
  const sig = signals[i];
  const clay = clayData[i] || null;
  const { score, tier } = scoreOne(sig, clay);
  if (tier === 0) continue;
  out.push({ json: { ...sig, clay_enriched: !!clay, icp_score: score, tier } });
}
return out;

// Drop rows without a valid technical buyer email.
const base = $('ICP Score + Filter').all().map(i => i.json);
const people = $input.all().map(i => i.json);

const out = [];
for (let i = 0; i < base.length; i++) {
  const row = base[i];
  const p = people[i] || {};
  if (!p.email || !p.email.includes('@')) continue;
  out.push({
    json: {
      ...row,
      contact_name:  p.name  || p.full_name || '',
      contact_email: p.email,
      contact_title: p.title || p.job_title  || ''
    }
  });
}
return out;

