// Parse Claude response, merge with qualified row, prepare Sheet payload.
const qualified = $('Keep Rows With Contact').all().map(i => i.json);
const claudeResp = $input.all().map(i => i.json);

const out = [];
for (let i = 0; i < qualified.length; i++) {
  const q = qualified[i];
  const resp = claudeResp[i] || {};
  const text = (resp.content && resp.content[0] && resp.content[0].text) || '{}';
  let parsed = { subject: '', body: '' };
  try {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) parsed = JSON.parse(match[0]);
  } catch (e) {
    parsed = { subject: '', body: text };
  }
  out.push({
    json: {
      timestamp: new Date().toISOString(),
      company: q.company_name,
      domain: q.company_domain,
      framework: q.framework,
      repo_url: q.repo_url,
      commit_date: q.detected_at,
      contact_name: q.contact_name,
      contact_email: q.contact_email,
      contact_title: q.contact_title,
      icp_score: q.icp_score,
      tier: q.tier,
      subject: parsed.subject || '',
      body: parsed.body || '',
      status: 'queued',
      org_login: q.org_login
    }
  });
}
return out;

// Log run statistics — number of signals, qualified leads, etc.
const detected  = $('Flatten + Extract Orgs').all().length;
const fresh     = $('Dedup Against State').all().length;
const domained  = $('Extract Domain').all().length;
const qualified = $('ICP Score + Filter').all().length;
const contacted = $('Keep Rows With Contact').all().length;
const written   = $input.all().length;

console.log(JSON.stringify({
  run_at: new Date().toISOString(),
  detected,
  fresh,
  domained,
  qualified,
  contacted,
  written
}));

return [{ json: { run_at: new Date().toISOString(), detected, fresh, domained, qualified, contacted, written } }];
